"use client";
import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  Rectangle,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
  type RectangleProps,
} from "recharts";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import { formatNumber, useChartHover } from "./chart-card";
import { ChartBarTrack } from "./chart-bar-track";
import { ChartFrame, DAYS, safeRatio, sum, WeekSwitcher } from "./pro-chart";
export interface StepsPoint {
  label: string;
  fullLabel?: string;
  value: number;
}
export interface StepsWeek {
  id: string;
  label: string;
  data: StepsPoint[];
}
export interface StepsCardProps {
  title?: string;
  data?: StepsPoint[];
  weeks?: StepsWeek[];
  defaultWeek?: string;
  onWeekChange?: (id: string) => void;
  className?: string;
  color?: string;
  goal?: number;
}
export const STEPS_DATA: StepsPoint[] = DAYS.map((label, i) => ({
  label,
  fullLabel: [
    "Monday",
    "Tuesday",
    "Wednesday",
    "Thursday",
    "Friday",
    "Saturday",
    "Sunday",
  ][i]!,
  value: [5600, 2200, 1900, 6300, 7100, 5300, 3200][i]!,
}));
const WEEKS: StepsWeek[] = [
  {
    id: "previous",
    label: "22 Jun - 28 Jun",
    data: STEPS_DATA.map((d, i) => ({
      ...d,
      value: [4200, 7200, 5100, 4000, 8100, 7900, 2000][i]!,
    })),
  },
  { id: "current", label: "29 Jun - 5 Jul", data: STEPS_DATA },
  {
    id: "next",
    label: "6 Jul - 12 Jul",
    data: STEPS_DATA.map((d, i) => ({
      ...d,
      value: [3200, 6400, 2300, 3800, 5200, 3900, 5400][i]!,
    })),
  },
];
type StepsBarProps = Omit<RectangleProps, "points"> & {
  index?: number;
  points: StepsPoint[];
  active: number | null;
  color: string;
  onInspect: (index: number | null) => void;
};
function StepsBar({
  points,
  active,
  color,
  onInspect,
  ...geometry
}: StepsBarProps) {
  const index = geometry.index ?? 0,
    point = points[index];
  return (
    <g
      role="button"
      tabIndex={-1}
      aria-label={`${point?.label}: ${formatNumber(point?.value ?? 0)} steps`}
      onMouseDown={(event) => event.preventDefault()}
      onClick={() => onInspect(index)}
      onFocus={() => onInspect(index)}
      onBlur={() => onInspect(null)}
    >
      <Rectangle
        {...geometry}
        radius={10}
        fill={
          active === index && color === "var(--color-chart-1)"
            ? "var(--color-chart-1-active)"
            : color
        }
      />
    </g>
  );
}
export function StepsCard({
  title = "Steps",
  data,
  weeks = WEEKS,
  defaultWeek = "current",
  onWeekChange,
  className,
  color = "var(--color-chart-1)",
  goal = 8000,
}: StepsCardProps = {}) {
  const [week, setWeek] = useState(
      Math.max(
        0,
        weeks.findIndex((w) => w.id === defaultWeek),
      ),
    ),
    hover = useChartHover(),
    active = hover.activeIndex,
    [plotDelay, setPlotDelay] = useState(0),
    reduced = useHydratedReducedMotion(),
    current = weeks[week],
    points = data ?? current?.data ?? [],
    requestedCeiling = Math.max(goal, ...points.map((p) => p.value)),
    ceiling =
      Number.isFinite(requestedCeiling) && requestedCeiling > 0
        ? requestedCeiling
        : 1,
    change = (delta: number) => {
      const next = (week + delta + weeks.length) % Math.max(1, weeks.length);
      setWeek(next);
      if (active != null && active >= (data ?? weeks[next]?.data ?? []).length)
        hover.clear();
      setPlotDelay(320);
      if (weeks[next]) onWeekChange?.(weeks[next]!.id);
    };
  const plotPoints = useMemo(
    () =>
      points.map((point) => ({
        ...point,
        plotValue: safeRatio(point.value, requestedCeiling) * ceiling,
      })),
    [points, requestedCeiling, ceiling],
  );
  return (
    <ChartFrame
      title={
        active == null
          ? title
          : (points[active]?.fullLabel ?? points[active]?.label ?? title)
      }
      value={
        active == null
          ? sum(points.map((p) => p.value))
          : (points[active]?.value ?? 0)
      }
      suffix={active == null ? "total steps" : "steps"}
      className={cx("rounded-[20px]", className)}
      height={330}
      padding="inset"
      animateNumber
      pulseKey={active}
      action={
        <WeekSwitcher
          compact
          label={current?.label ?? "This week"}
          onPrevious={() => change(-1)}
          onNext={() => change(1)}
        />
      }
    >
      <div className="-mx-[5.5px] min-h-0 flex-1">
        <ResponsiveContainer width="100%" height="100%">
          <BarChart
            data={plotPoints}
            margin={{ top: 4, right: 0, left: 0, bottom: 0 }}
            barCategoryGap={4.5}
            {...hover.handlers}
          >
            <YAxis
              hide
              domain={
                data || weeks !== WEEKS || goal !== 8000
                  ? [0, ceiling]
                  : [0, "auto"]
              }
            />
            <XAxis
              dataKey="label"
              axisLine={false}
              tickLine={false}
              tick={{ fontSize: 12, fill: "var(--color-text-secondary)" }}
              height={26}
              tickMargin={8}
            />
            <Tooltip content={() => null} cursor={false} />
            <Bar
              dataKey="plotValue"
              fill={color}
              maxBarSize={50}
              radius={10}
              isAnimationActive={!reduced}
              animationDuration={450}
              animationEasing="ease"
              animationBegin={plotDelay}
              background={(value: unknown) => {
                const p = value as RectangleProps & { index?: number };
                return <ChartBarTrack {...p} active={active === p.index} />;
              }}
              shape={
                <StepsBar
                  points={points}
                  active={active}
                  color={color}
                  onInspect={hover.setActiveIndex}
                />
              }
            />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </ChartFrame>
  );
}
